<?php require_once __DIR__.'/security.php';
function hms_billing_ready(mysqli $c):bool{$r=hms_db_query($c,"SELECT 1 FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name='billing_invoices'");return $r&&$r->num_rows===1;}
function hms_billing_refresh(mysqli $c,int $invoiceId):void{$r=hms_db_query($c,'SELECT COALESCE(SUM(line_total),0) subtotal FROM billing_invoice_items WHERE invoice_id=?',[$invoiceId])->fetch_assoc();$p=hms_db_query($c,'SELECT COALESCE(SUM(amount),0) paid FROM billing_payments WHERE invoice_id=?',[$invoiceId])->fetch_assoc();$i=hms_db_query($c,'SELECT discount_amount,tax_amount FROM billing_invoices WHERE id=? FOR UPDATE',[$invoiceId])->fetch_assoc();if(!$i)throw new InvalidArgumentException('Invoice not found.');$total=max(0,(float)$r['subtotal']-(float)$i['discount_amount']+(float)$i['tax_amount']);$paid=min($total,(float)$p['paid']);$balance=$total-$paid;$status=$balance<=0?'paid':($paid>0?'partially_paid':'unpaid');hms_db_query($c,'UPDATE billing_invoices SET subtotal=?,total_amount=?,amount_paid=?,balance_amount=?,status=? WHERE id=?',[$r['subtotal'],$total,$paid,$balance,$status,$invoiceId]);}
function hms_billing_notice():string{return 'Apply SQL File/migrations/005_billing_payments.sql to enable billing.';}
